svg.script:
(() => {
  const controls = Array.from(document.querySelectorAll('.machine-control'));
  const points = Array.from(document.querySelectorAll('.data-point'));
  const chips = Array.from(document.querySelectorAll('.machine-chip'));
  const heading = document.getElementById('details-heading');
  const copy = document.getElementById('details-copy');
  let pinnedControl = null;

  const defaultHeading = 'Explore the results';
  const defaultCopy = 'Hover, focus, or tap a row. Select a machine above to keep its results highlighted.';

  function setHash(host) {
    try {
      const next = host ? `#${encodeURIComponent(host)}` : `${location.pathname}${location.search}`;
      history.replaceState(null, '', next);
    } catch (_) {
      // The static chart still works if its embedding context blocks history access.
    }
  }

  function render(control, isPinned = false) {
    const series = control && control.dataset.series !== 'all'
      ? control.dataset.series
      : null;

    points.forEach((point) => {
      const active = series !== null && point.dataset.series === series;
      point.classList.toggle('is-active', active);
      point.classList.toggle('is-dimmed', series !== null && !active);
      point.setAttribute('aria-pressed', String(isPinned && active));
    });

    chips.forEach((chip) => {
      const active = series === null
        ? chip.dataset.series === 'all'
        : chip.dataset.series === series;
      chip.classList.toggle('is-active', active);
      chip.setAttribute('aria-pressed', String(isPinned ? active : series === null && active));
    });

    heading.textContent = control ? control.dataset.heading : defaultHeading;
    copy.textContent = control ? control.dataset.detail : defaultCopy;
  }

  function restorePinned() {
    render(pinnedControl, Boolean(pinnedControl));
  }

  function clearSelection(updateLocation = true) {
    pinnedControl = null;
    render(null, false);
    if (updateLocation) setHash('');
  }

  function toggle(control) {
    if (control.dataset.series === 'all' || pinnedControl === control) {
      clearSelection();
      return;
    }
    pinnedControl = control;
    render(control, true);
    setHash(control.dataset.host || '');
  }

  controls.forEach((control) => {
    control.addEventListener('pointerenter', () => render(control, false));
    control.addEventListener('pointerleave', restorePinned);
    control.addEventListener('focus', () => render(control, false));
    control.addEventListener('blur', restorePinned);
    control.addEventListener('click', () => toggle(control));
    control.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        toggle(control);
      } else if (event.key === 'Escape') {
        event.preventDefault();
        clearSelection();
      }
    });
  });

  const initialHost = decodeURIComponent(location.hash.slice(1));
  const initialChip = initialHost
    ? chips.find((chip) => chip.dataset.host === initialHost)
    : null;
  if (initialChip) {
    pinnedControl = initialChip;
    render(initialChip, true);
  } else {
    render(null, false);
  }
})();
